float scene(vec3 rayPos,vec3 rayDir,out vec3 normal, out vec3 color){
    float d = NOHIT;

    #define VAXIS vec3(0,1,0)
    vec3 rx =normalize(cross(rayDir,VAXIS)),ry=cross(rx,rayDir); 
    mat3 vm=mat3(rx,ry,rayDir);

    int  n= pts.length()/3;
     for(int ci=min(iFrame,0);ci<n;ci++) {

         vec4 pa=pts[ci*3];
         vec4 pb=pts[ci*3+1];
         vec4 col=pts[ci*3+2];

         vec4 sz=vec4((pb-pa).xyz*.5,0);
         vec4 tk=vec4(pa.w,pb.w,0,0);

         for(float j=min(float(iFrame),0.1);j<1.;j+=.4){
             vec3 oNor;
             tk.z=j;
             //tk.w=j<.4 ? col.w*.1:0.;

             vec3 oc=(pb+pa).xyz*.5 + vec3(j*20.-10.,0,0);
                if(ci==0 && j>.1) continue;
             if ( length(cross(oc-rayPos,rayDir))>length(sz)+max(tk.x,tk.y)) continue;

             float t= iSupportFunction( rayPos-oc , vm, sz,tk,oNor);
             if( d>t && t>0. ){
                 d=t-.0001;
                 normal= oNor;
                 color=min(vec3(1),col.xyz+vec3(1.-j,j*.5-.5,j-1.)*.3);    
             }
         }
     }
     return d;
}

void mainImage( out vec4 Q, in vec2 I )
{

    vec3 sunDir = normalize(vec3(0.1,.05,0.2));
    vec3 sunColor = vec3(1,.8,.6);
    vec3 skyColor = vec3(.7,.8,1);
    vec3 difColor;

    float a = iMouse.z<=0.?cos(iTime*.3)*1.2:iMouse.x/iResolution.x*6.28-3.14, 
          b = iMouse.z<=0.?1.:iMouse.y/iResolution.y*3.14; 
    vec3  camPos = vec3(sin(a)*sin(b),cos(b), cos(a)*sin(b))*15.;    	
    vec3  f =-normalize(camPos), r = normalize(cross(VAXIS, f)),
          rayDir = normalize(mat3(f, r ,cross(f, r))*vec3(1,(I-iResolution.xy*.5)/iResolution.y));

    vec3 n;

    float d= scene(camPos,rayDir,n,difColor);

    if (d<NOHIT)
    {                                   
        Q = vec4(difColor*skyColor*(n.y*0.5+0.5),0.);
        float suncos = dot(n,sunDir);
        if (suncos>0.0 && scene(camPos +rayDir*d,sunDir,n,difColor)==NOHIT)
              Q.xyz += difColor * suncos * sunColor;                  
    }
    else
    {
        Q.xyz = skyColor*(dot(rayDir,sunDir)*-0.3+1.0);
        if (dot(sunDir,rayDir)>0.0) 
        {
         float f = max(length(cross(sunDir,rayDir))*10.0,1.0);		
         Q.xyz += sunColor*40.0/(f*f*f*f);
        }       
    }

}

#define TOLERANCE 1e-8
#define ITERATIONS 20
#define NOHIT 1e30

vec3 supMax(vec3 d, vec3 a, vec3 b) { return dot(d,a) > dot(d,b) ? a : b;}

//  Given vm as view matrix, casts ray from ro, and estimates depth and normal 
//   sz= edges position,  tk= thickness and smoothing
float iSupportFunction( in vec3 ro, inout mat3 vm, vec4 sz,vec4 tk, out vec3 normal)
{   
    vec3 dir, tmp;   
    vec3 a,b,c,d;

    float d0=- dot(ro,vm[2]);
    ro*=vm;

    #define perp2d(v)  ((v).yx*vec2(-1,1))  //(cross(v,vec3(0,0,-1)).xy) 
    a=vec3(ro.xy, 0);

    dir=vec3(-a.xy, 0.);
    for(int st=0;st<3;st++){  
      int N=0; if(st>0) N=ITERATIONS;
      for (int i = 0;i <=N; i++){

        vec3 sd=dir*transpose(vm);
        //ANY SUPPORT FUNCTION HERE...

        //capsule
        d=  supMax( sd, sz.xyz+normalize(sd)*tk.x,-sz.xyz +normalize(sd)*tk.y);
        //mix with box
        d=mix(d,sign(sd)*(abs(sz.xyz)+(tk.x+tk.y)*.5),tk.z);

        d*=vm;d+=vec3(ro.xy, 0);

        if(st>1 && i>12) d.xy+=fract(a.xy)*tk.w-tk.w*.5; //microfacets

        if(st==0){              
                b=d;
                if (dot(-a.xy, b.xy) <= 0.) return NOHIT;
                dir = vec3(perp2d(b-a),0.);
                if (dot(dir.xy, a.xy) >= 0.) {  dir.xy *= -1.; tmp = a; a = b; b = tmp;}            
        }
        else if(st==1){            
                c=d;
                if (dot(c.xy, dir.xy) <= 0.) return (NOHIT);                    
                if (i == 5) return (NOHIT);
                if (dot(dir.xy = perp2d(c-a), c.xy) < 0.) {b = c;}
                else if (dot(dir.xy = perp2d(b-c), c.xy) < 0.)  {a = c;}
                else break;       
        }
        else if(st==2){               
                if (abs(dot(dir, d) - dot(dir, a)) < TOLERANCE) break;
                vec3 abc = step(vec3(0),vec3(
                        dot(perp2d(d-a), d.xy) ,
                        dot(perp2d(d-b), d.xy) ,
                        dot(perp2d(d-c), d.xy)));
                abc= abc* (1.-abc.yzx) ;

                c = abc.x>0.? d:c;
                a = abc.y>0.? d:a;
                b = abc.z>0.? d:b;

                dir = normalize(cross(b-a, c-a));  
        }
      }
    }
    normal = -normalize(cross(b-a, c-a)) ;
    float depth = a.z + dot(a.xy, normal.xy)/normal.z ;   
    normal=normal*transpose(vm);
    return  (  -depth +d0);   
}
